class Solution {
    public String nearestPalindromic(String n) {
        long target = Long.parseLong(n);
        int len = n.length();
        int prefixLen = (len + 1) / 2;
        long prefix = Long.parseLong(n.substring(0, prefixLen));
        Set<Long> candidates = new HashSet<>();
        candidates.add(pow10(len - 1) - 1);
        candidates.add(pow10(len) + 1);

        for (long nextPrefix = prefix - 1; nextPrefix <= prefix + 1; nextPrefix++) {
            if (nextPrefix < 0) continue;
            String left = Long.toString(nextPrefix);
            if (left.length() != prefixLen) continue;
            candidates.add(buildPalindrome(left, len));
        }

        long best = -1;
        for (long candidate : candidates) {
            if (candidate == target) continue;
            if (best == -1
                    || Math.abs(candidate - target) < Math.abs(best - target)
                    || (Math.abs(candidate - target) == Math.abs(best - target) && candidate < best)) {
                best = candidate;
            }
        }
        return Long.toString(best);
    }

    private long buildPalindrome(String left, int totalLength) {
        StringBuilder builder = new StringBuilder(left);
        int start = totalLength % 2 == 0 ? left.length() - 1 : left.length() - 2;
        for (int i = start; i >= 0; i--) {
            builder.append(left.charAt(i));
        }
        return Long.parseLong(builder.toString());
    }

    private long pow10(int exp) {
        long value = 1;
        for (int i = 0; i < exp; i++) value *= 10;
        return value;
    }
}

class Solution {
    public String nearestPalindromic(String n) {
        if (n.equals("1")) return "0";
        long target = Long.parseLong(n);
        long lower = lowerPalindrome(n, target);
        long higher = higherPalindrome(n, target);
        if (target - lower <= higher - target) {
            return Long.toString(lower);
        }
        return Long.toString(higher);
    }

    private long lowerPalindrome(String n, long target) {
        int len = n.length();
        int prefixLen = (len + 1) / 2;
        long prefix = Long.parseLong(n.substring(0, prefixLen));
        long direct = mirror(prefix, len);
        if (direct < target) return direct;
        prefix--;
        if (prefix <= 0 || Long.toString(prefix).length() < prefixLen) {
            return pow10(len - 1) - 1;
        }
        return mirror(prefix, len);
    }

    private long higherPalindrome(String n, long target) {
        int len = n.length();
        int prefixLen = (len + 1) / 2;
        long prefix = Long.parseLong(n.substring(0, prefixLen));
        long direct = mirror(prefix, len);
        if (direct > target) return direct;
        prefix++;
        if (Long.toString(prefix).length() > prefixLen) {
            return pow10(len) + 1;
        }
        return mirror(prefix, len);
    }

    private long mirror(long prefix, int len) {
        String left = Long.toString(prefix);
        StringBuilder builder = new StringBuilder(left);
        int start = len % 2 == 0 ? left.length() - 1 : left.length() - 2;
        for (int i = start; i >= 0; i--) {
            builder.append(left.charAt(i));
        }
        return Long.parseLong(builder.toString());
    }

    private long pow10(int exp) {
        long value = 1;
        for (int i = 0; i < exp; i++) value *= 10;
        return value;
    }
}

class Solution {
    public String nearestPalindromic(String n) {
        long target = Long.parseLong(n);
        int len = n.length();
        int prefixLen = (len + 1) / 2;
        long prefix = Long.parseLong(n.substring(0, prefixLen));
        long[] candidates = new long[5];
        int size = 0;
        candidates[size++] = pow10(len - 1) - 1;
        candidates[size++] = pow10(len) + 1;

        for (long adjusted = prefix - 1; adjusted <= prefix + 1; adjusted++) {
            if (adjusted < 0) continue;
            if (Long.toString(adjusted).length() != prefixLen) continue;
            candidates[size++] = mirrorNumber(adjusted, len % 2 == 1);
        }

        long best = -1;
        for (int i = 0; i < size; i++) {
            long candidate = candidates[i];
            if (candidate == target) continue;
            long distance = Math.abs(candidate - target);
            long bestDistance = best == -1 ? Long.MAX_VALUE : Math.abs(best - target);
            if (distance < bestDistance || (distance == bestDistance && candidate < best)) {
                best = candidate;
            }
        }
        return Long.toString(best);
    }

    private long mirrorNumber(long prefix, boolean oddLength) {
        long result = prefix;
        if (oddLength) prefix /= 10;
        while (prefix > 0) {
            result = result * 10 + prefix % 10;
            prefix /= 10;
        }
        return result;
    }

    private long pow10(int exp) {
        long value = 1;
        for (int i = 0; i < exp; i++) value *= 10;
        return value;
    }
}

class Solution {
    public String nearestPalindromic(String n) {
        int len = n.length();
        int prefixLen = (len + 1) / 2;
        long prefix = Long.parseLong(n.substring(0, prefixLen));
        Set<String> candidates = new HashSet<>();
        candidates.add(lowerBoundary(len));
        candidates.add(upperBoundary(len));
        for (long adjusted = prefix - 1; adjusted <= prefix + 1; adjusted++) {
            if (adjusted < 0) continue;
            String left = Long.toString(adjusted);
            if (left.length() != prefixLen) continue;
            candidates.add(mirror(left, len));
        }

        java.math.BigInteger target = new java.math.BigInteger(n);
        java.math.BigInteger best = null;
        for (String candidateText : candidates) {
            if (candidateText.equals(n)) continue;
            java.math.BigInteger candidate = new java.math.BigInteger(candidateText);
            if (best == null
                    || candidate.subtract(target).abs().compareTo(best.subtract(target).abs()) < 0
                    || (candidate.subtract(target).abs().equals(best.subtract(target).abs())
                    && candidate.compareTo(best) < 0)) {
                best = candidate;
            }
        }
        return best.toString();
    }

    private String lowerBoundary(int len) {
        if (len == 1) return "0";
        return "9".repeat(len - 1);
    }

    private String upperBoundary(int len) {
        return "1" + "0".repeat(len - 1) + "1";
    }

    private String mirror(String left, int totalLength) {
        StringBuilder builder = new StringBuilder(left);
        int start = totalLength % 2 == 0 ? left.length() - 1 : left.length() - 2;
        for (int i = start; i >= 0; i--) {
            builder.append(left.charAt(i));
        }
        return builder.toString();
    }
}

class Solution {
    public String nearestPalindromic(String n) {
        if (n.equals("1")) return "0";
        long target = Long.parseLong(n);
        String previous = previousPalindrome(n);
        String next = nextPalindrome(n);
        long previousValue = Long.parseLong(previous);
        long nextValue = Long.parseLong(next);
        if (target - previousValue <= nextValue - target) {
            return previous;
        }
        return next;
    }

    private String previousPalindrome(String n) {
        int len = n.length();
        int prefixLen = (len + 1) / 2;
        String prefixText = n.substring(0, prefixLen);
        String direct = mirrorSameLength(prefixText, len);
        long target = Long.parseLong(n);
        if (Long.parseLong(direct) < target) return direct;
        long borrowed = Long.parseLong(prefixText) - 1;
        if (borrowed <= 0 || Long.toString(borrowed).length() < prefixLen) {
            return len == 1 ? "0" : "9".repeat(len - 1);
        }
        return mirrorSameLength(Long.toString(borrowed), len);
    }

    private String nextPalindrome(String n) {
        int len = n.length();
        int prefixLen = (len + 1) / 2;
        String prefixText = n.substring(0, prefixLen);
        String direct = mirrorSameLength(prefixText, len);
        long target = Long.parseLong(n);
        if (Long.parseLong(direct) > target) return direct;
        long carried = Long.parseLong(prefixText) + 1;
        if (Long.toString(carried).length() > prefixLen) {
            return "1" + "0".repeat(len - 1) + "1";
        }
        return mirrorSameLength(Long.toString(carried), len);
    }

    private String mirrorSameLength(String left, int totalLength) {
        StringBuilder builder = new StringBuilder(left);
        int start = totalLength % 2 == 0 ? left.length() - 1 : left.length() - 2;
        for (int i = start; i >= 0; i--) {
            builder.append(left.charAt(i));
        }
        return builder.toString();
    }
}
